import pandas as pd
import numpy as np

# Load data
df = pd.read_csv('chunks_csv/outlierr/2022_transport.csv')
adj_df = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Prepare adjacency dictionary
adjacency = {}
for borough in df['borough']:
    neighbors = adj_df[adj_df['borough'] == borough]['neighbor'].tolist()
    adjacency[borough] = neighbors

# Initialize variables
values = df.set_index('borough')['Transport_value'].to_dict()
boroughs = list(values.keys())
n = len(boroughs)

# Iterative R method implementation
def iterative_r(values, adjacency, max_iter=10, tol=1e-6):
    residuals = {}
    masked = set()

    for _ in range(max_iter):
        # Calculate neighborhood averages excluding masked boroughs
        neighborhood_avgs = {}
        for b in boroughs:
            if b in masked:
                continue
            neighbors = [n for n in adjacency[b] if n not in masked]
            if not neighbors:
                neighborhood_avgs[b] = np.nan
                continue
            neighbor_values = [values[n] for n in neighbors]
            neighborhood_avgs[b] = np.mean(neighbor_values)

        # Fit global regression (value ~ neighborhood_avg)
        X = []
        y = []
        for b in boroughs:
            if b in masked or np.isnan(neighborhood_avgs.get(b, np.nan)):
                continue
            X.append(neighborhood_avgs[b])
            y.append(values[b])

        if len(X) < 2:
            break

        X = np.array(X)
        y = np.array(y)
        X = np.vstack([X, np.ones(len(X))]).T
        beta = np.linalg.lstsq(X, y, rcond=None)[0]

        # Calculate residuals
        current_residuals = {}
        for b in boroughs:
            if b in masked or np.isnan(neighborhood_avgs.get(b, np.nan)):
                continue
            pred = beta[0] * neighborhood_avgs[b] + beta[1]
            current_residuals[b] = values[b] - pred

        # Find most extreme residual
        if not current_residuals:
            break

        max_residual_borough = max(current_residuals.items(), key=lambda x: abs(x[1]))[0]
        max_residual = current_residuals[max_residual_borough]

        # Check if we should mask this borough
        if abs(max_residual) > 2 * np.std(list(current_residuals.values())):
            residuals[max_residual_borough] = max_residual
            masked.add(max_residual_borough)
        else:
            break

    # Final residuals for all boroughs (including masked ones)
    neighborhood_avgs = {}
    for b in boroughs:
        neighbors = [n for n in adjacency[b] if n not in masked]
        if not neighbors:
            neighborhood_avgs[b] = np.nan
            continue
        neighbor_values = [values[n] for n in neighbors]
        neighborhood_avgs[b] = np.mean(neighbor_values)

    X_final = []
    y_final = []
    for b in boroughs:
        if np.isnan(neighborhood_avgs.get(b, np.nan)):
            continue
        X_final.append(neighborhood_avgs[b])
        y_final.append(values[b])

    if len(X_final) >= 2:
        X_final = np.array(X_final)
        y_final = np.array(y_final)
        X_final = np.vstack([X_final, np.ones(len(X_final))]).T
        beta_final = np.linalg.lstsq(X_final, y_final, rcond=None)[0]

        final_residuals = {}
        for b in boroughs:
            if np.isnan(neighborhood_avgs.get(b, np.nan)):
                final_residuals[b] = np.nan
                continue
            pred = beta_final[0] * neighborhood_avgs[b] + beta_final[1]
            final_residuals[b] = values[b] - pred

        # Standardize residuals
        valid_residuals = [r for r in final_residuals.values() if not np.isnan(r)]
        if len(valid_residuals) > 1:
            mean_res = np.mean(valid_residuals)
            std_res = np.std(valid_residuals)
            z_scores = {b: (r - mean_res)/std_res if not np.isnan(r) else np.nan 
                       for b, r in final_residuals.items()}
        else:
            z_scores = {b: np.nan for b in boroughs}
    else:
        z_scores = {b: np.nan for b in boroughs}

    return z_scores

# Calculate z-scores
z_scores = iterative_r(values, adjacency)

# Get City of London result
city_z = z_scores.get('City of London', np.nan)

# Determine final answer
if np.isnan(city_z):
    print("FINAL ANSWER: NOT AN OUTLIER (z = nan)")
elif city_z > 2:
    print(f"FINAL ANSWER: OUTLIER - HIGH (z = {city_z})")
elif city_z < -2:
    print(f"FINAL ANSWER: OUTLIER - LOW (z = {city_z})")
else:
    print(f"FINAL ANSWER: NOT AN OUTLIER (z = {city_z})")
